{
  "evidence": [
    {
      "ref_id": "p055",
      "group_ids": [
        "E2"
      ],
      "quote": "翰森製藥持續關注人力資源政策及相關方需求的變化,並開展合規性評估。我們聘請外部法律顧問團隊,對招 聘、合同簽訂、考勤休假等關鍵環節進行全程審核,並通過數字化合同系統與法務專項審查,確保勞動合同及 保密協議的簽署完全合規,實現合同條款與政策要求一致,保障所有勞動合同合法有效。",
      "kind": "policy/mechanism/action/result/plan/boundary",
      "period": "2025年1月1日至2025年12月31日",
      "scope": "未明确",
      "relevance": "披露了劳动合同签订环节的审核机制及确保合同合规有效的措施，符合劳动合同保障的具体政策或安排。"
    },
    {
      "ref_id": "p048",
      "group_ids": [
        "P1"
      ],
      "quote": "提供合理薪酬福利: 瞭解同行業、同地區的薪酬水平,制定具有競爭力的薪資標準和工資增長機制,保證員工的收入不低於 同崗位市場平均水平和當地最低工資水平。同時提供包括「五險一金」等法定福利在內的更多生活保障,減輕員工的生活負 擔和後顧之憂。",
      "kind": "policy/mechanism/action/result/plan/boundary",
      "period": "2025年1月1日至2025年12月31日",
      "scope": "员工",
      "relevance": "披露了保证员工收入不低于当地最低工资水平的具体保障政策，符合工资支付保障中的最低工资保障内容。"
    },
    {
      "ref_id": "p031",
      "group_ids": [
        "W1"
      ],
      "quote": "翰森製藥建立了多樣化的福利保障計劃。在法定「五險一金」全面覆蓋基礎上,針對特定員工,我們設置了補 充醫療保險與健康體檢、學歷提升資助、專利申報激勵等福利包,有效提升人才的薪酬競爭力。",
      "kind": "policy/mechanism/action/result/plan/boundary",
      "period": "2025年1月1日至2025年12月31日",
      "scope": "特定员工（针对补充福利）；全体员工（针对五险一金覆盖声明）",
      "relevance": "披露了法定“五险一金”的全面覆盖情况，属于法定社会保障及基本福利的政策与事实。"
    },
    {
      "ref_id": "p037",
      "group_ids": [
        "W2"
      ],
      "quote": "員工年度體檢、員工補充商業醫療保險、高溫津貼、職場心理諮詢、健身設施等",
      "kind": "policy/mechanism/action/result/plan/boundary",
      "period": "2025年1月1日至2025年12月31日",
      "scope": "未明确",
      "relevance": "列出了员工补充商业医疗保险、高温津贴等具体补充福利项目，符合补充福利的披露要求。"
    },
    {
      "ref_id": "p041",
      "group_ids": [
        "W3"
      ],
      "quote": "育兒假、工作日哺乳時間、哺乳室、靈活工作時間、子女商業醫療險等",
      "kind": "policy/mechanism/action/result/plan/boundary",
      "period": "2025年1月1日至2025年12月31日",
      "scope": "未明确",
      "relevance": "披露了育儿假、哺乳室、子女商业医疗险等家庭与生活支持资源和服务，符合家庭与生活支持的披露要求。"
    }
  ]
}
